-- ----------------------------
-- Procedure structure for edit_categoria
-- ----------------------------
DROP PROCEDURE IF EXISTS `edit_categoria`;
delimiter ;;
CREATE PROCEDURE `edit_categoria`(parId SMALLINT, parNom VARCHAR(100), parDes VARCHAR(255))
BEGIN
  UPDATE categoria
	SET
	categoria.Nombre_Cat = parNom,
	categoria.Descripcion_Cat = parDes
	WHERE parId = Id_Categoria;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for edit_marca
-- ----------------------------
DROP PROCEDURE IF EXISTS `edit_marca`;
delimiter ;;
CREATE PROCEDURE `edit_marca`(parId SMALLINT, parNom VARCHAR(100), parDes VARCHAR(255))
BEGIN
  UPDATE marca
	SET
	marca.Nombre_Marca = parNom,
	marca.Descripcion_Marca = parDes
	WHERE parId = Id_Marca;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for edit_presentacion
-- ----------------------------
DROP PROCEDURE IF EXISTS `edit_presentacion`;
delimiter ;;
CREATE PROCEDURE `edit_presentacion`(parId SMALLINT, parDes VARCHAR(255))
BEGIN
UPDATE presentacion 
SET
presentacion.Descripcion = parDes
WHERE parId = presentacion.Id_Presentacion;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for edit_proveedor
-- ----------------------------
DROP PROCEDURE IF EXISTS `edit_proveedor`;
delimiter ;;
CREATE PROCEDURE `edit_proveedor`(parId SMALLINT, parNom VARCHAR(20), parTel VARCHAR(10))
BEGIN
  UPDATE proveedor
	SET
	proveedor.Nombre = parNom,
	proveedor.Telefono = parTel
	WHERE parId = Id_Proveedor;
END
;;
delimiter ;

